"""Generates CldrData.h from a pinned CLDR JSON release for the cultures Herta ships.

Run from the repository root when adding a culture or updating CLDR, listing every culture shipped:

    python External/cldr/GenerateCldrData.py en pl ru

It downloads the pinned files, so it is dependency-update tooling, never part of a build.
"""

import json
import sys
import urllib.request

TAG = "49.0.0"
BASE = f"https://raw.githubusercontent.com/unicode-org/cldr-json/{TAG}/cldr-json"
OUTPUT = "External/cldr/CldrData.h"
PLURAL_CATEGORIES = ["zero", "one", "two", "few", "many"]
MONTH_KEYS = [str(Month) for Month in range(1, 13)]
DAY_KEYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"]
STYLES = ["full", "long", "medium", "short"]


def fetch(path):
    with urllib.request.urlopen(f"{BASE}/{path}") as Response:
        return json.loads(Response.read().decode("utf-8"))


def literal(Text):
    Escaped = Text.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{Escaped}"'


def strings(Values):
    return "{" + ", ".join(literal(Value) for Value in Values) + "}"


def pattern(Value):
    # Some formats carry alternates as objects; the plain pattern is the default.
    return Value if isinstance(Value, str) else Value["_value"]


def main(Cultures):
    Plurals = fetch("cldr-core/supplemental/plurals.json")["supplemental"]["plurals-type-cardinal"]
    Parents = fetch("cldr-core/supplemental/parentLocales.json")["supplemental"]["parentLocales"]["parentLocale"]
    License = urllib.request.urlopen(f"https://raw.githubusercontent.com/unicode-org/cldr-json/{TAG}/LICENSE").read().decode("utf-8")
    Entries = []
    for Culture in Cultures:
        Numbers = fetch(f"cldr-numbers-full/main/{Culture}/numbers.json")["main"][Culture]["numbers"]
        Calendar = fetch(f"cldr-dates-full/main/{Culture}/ca-gregorian.json")["main"][Culture]["dates"]["calendars"]["gregorian"]
        Symbols = Numbers["symbols-numberSystem-latn"]
        Rules = Plurals[Culture]
        Plural = [Rules.get(f"pluralRule-count-{Category}", "").split("@")[0].strip() for Category in PLURAL_CATEGORIES]
        Months = Calendar["months"]
        Days = Calendar["days"]
        Periods = Calendar["dayPeriods"]["format"]["abbreviated"]
        Entries.append(
            "    FLocale{\n"
            f"        .Name = {literal(Culture)},\n"
            f"        .Parent = {literal(Parents.get(Culture, ''))},\n"
            f"        .PluralRules = {strings(Plural)},\n"
            f"        .Decimal = {literal(Symbols['decimal'])},\n"
            f"        .Group = {literal(Symbols['group'])},\n"
            f"        .Minus = {literal(Symbols['minusSign'])},\n"
            f"        .Percent = {literal(Symbols['percentSign'])},\n"
            f"        .DecimalPattern = {literal(Numbers['decimalFormats-numberSystem-latn']['standard'])},\n"
            f"        .PercentPattern = {literal(Numbers['percentFormats-numberSystem-latn']['standard'])},\n"
            f"        .MinimumGroupingDigits = {int(Numbers.get('minimumGroupingDigits', '1'))},\n"
            f"        .DateFormats = {strings(pattern(Calendar['dateFormats'][Style]) for Style in STYLES)},\n"
            f"        .TimeFormats = {strings(pattern(Calendar['timeFormats'][Style]) for Style in STYLES)},\n"
            f"        .DateTimeFormats = {strings(pattern(Calendar['dateTimeFormats'][Style]) for Style in STYLES)},\n"
            f"        .MonthsWide = {strings(Months['format']['wide'][Key] for Key in MONTH_KEYS)},\n"
            f"        .MonthsAbbreviated = {strings(Months['format']['abbreviated'][Key] for Key in MONTH_KEYS)},\n"
            f"        .MonthsStandalone = {strings(Months['stand-alone']['wide'][Key] for Key in MONTH_KEYS)},\n"
            f"        .DaysWide = {strings(Days['format']['wide'][Key] for Key in DAY_KEYS)},\n"
            f"        .DaysAbbreviated = {strings(Days['format']['abbreviated'][Key] for Key in DAY_KEYS)},\n"
            f"        .DayPeriods = {strings([Periods['am'], Periods['pm']])},\n"
            "    },\n"
        )

    LicenseComment = "\n".join(("// " + Line).rstrip() for Line in License.strip().splitlines())
    Header = (
        f"// Generated by External/cldr/GenerateCldrData.py from CLDR JSON {TAG} for {', '.join(Cultures)}; do not edit.\n"
        "//\n"
        f"{LicenseComment}\n"
        "\n"
        "#pragma once\n"
        "\n"
        "#include <array>\n"
        "#include <string_view>\n"
        "\n"
        "namespace Herta::Cldr\n"
        "{\n"
        f"inline constexpr std::string_view Version = {literal(TAG)};\n"
        "\n"
        "// One culture's data in CLDR's own syntax: plural rule conditions without samples, number and date patterns, and names, all UTF-8.\n"
        "struct FLocale\n"
        "{\n"
        "    std::string_view Name;\n"
        "    // The culture to fall back to before the source language, or empty.\n"
        "    std::string_view Parent;\n"
        "    // Conditions for zero, one, two, few, and many; other holds where none does. Empty conditions never hold.\n"
        "    std::array<std::string_view, 5> PluralRules;\n"
        "    std::string_view Decimal;\n"
        "    std::string_view Group;\n"
        "    std::string_view Minus;\n"
        "    std::string_view Percent;\n"
        "    std::string_view DecimalPattern;\n"
        "    std::string_view PercentPattern;\n"
        "    // Grouping starts once the integer part has this many digits more than one group.\n"
        "    int MinimumGroupingDigits;\n"
        "    // Full, long, medium, and short.\n"
        "    std::array<std::string_view, 4> DateFormats;\n"
        "    std::array<std::string_view, 4> TimeFormats;\n"
        "    std::array<std::string_view, 4> DateTimeFormats;\n"
        "    // January first; format forms are used inside dates, the standalone form alone.\n"
        "    std::array<std::string_view, 12> MonthsWide;\n"
        "    std::array<std::string_view, 12> MonthsAbbreviated;\n"
        "    std::array<std::string_view, 12> MonthsStandalone;\n"
        "    // Sunday first.\n"
        "    std::array<std::string_view, 7> DaysWide;\n"
        "    std::array<std::string_view, 7> DaysAbbreviated;\n"
        "    std::array<std::string_view, 2> DayPeriods;\n"
        "};\n"
        "\n"
        "inline constexpr std::array Locales{\n"
        + "".join(Entries)
        + "};\n"
        "}\n"
    )

    with open(OUTPUT, "w", encoding="utf-8", newline="\n") as File:
        File.write(Header)


if __name__ == "__main__":
    main(sys.argv[1:] or ["en", "pl", "ru"])
